    Cluster.add_member(:termination_protected, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'TerminationProtected', traits: {"smithy.api#documentation" => "<p>Indicates whether Amazon EMR will lock the cluster to prevent the Amazon EC2 instances from being terminated by an API call or user intervention, or in\n         the event of a cluster error.</p>"}))
    Cluster.add_member(:unhealthy_node_replacement, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanObject, location_name: 'UnhealthyNodeReplacement', traits: {"smithy.api#documentation" => "<p>Indicates whether Amazon EMR should gracefully replace Amazon EC2\n         core instances that have degraded within the cluster.</p>"}))
    Cluster.add_member(:visible_to_all_users, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'VisibleToAllUsers', traits: {"smithy.api#documentation" => "<p>Indicates whether the cluster is visible to IAM principals in the Amazon Web Services account associated with the cluster. When <code>true</code>, IAM principals in the Amazon Web Services account can perform Amazon EMR cluster\n         actions on the cluster that their IAM policies allow. When\n            <code>false</code>, only the IAM principal that created the cluster and\n         the Amazon Web Services account root user can perform Amazon EMR actions, regardless\n         of IAM permissions policies attached to other IAM\n         principals.</p>\n         <p>The default value is <code>true</code> if a value is not provided when creating a\n         cluster using the Amazon EMR API <a>RunJobFlow</a> command, the CLI\n         <a href=\"https://docs.aws.amazon.com/cli/latest/reference/emr/create-cluster.html\">create-cluster</a> command, or the Amazon Web Services Management Console.</p>"}))
