    OnDemandCapacityReservationOptions.add_member(:usage_strategy, Smithy::Schema::Shapes::ShapeRef.new(shape: OnDemandCapacityReservationUsageStrategy, location_name: 'UsageStrategy', traits: {"smithy.api#documentation" => "<p>Indicates whether to use unused Capacity Reservations for fulfilling On-Demand\n         capacity.</p>\n         <p>If you specify <code>use-capacity-reservations-first</code>, the fleet uses unused\n         Capacity Reservations to fulfill On-Demand capacity up to the target On-Demand capacity. If\n         multiple instance pools have unused Capacity Reservations, the On-Demand allocation\n         strategy (<code>lowest-price</code>) is applied. If the number of unused Capacity\n         Reservations is less than the On-Demand target capacity, the remaining On-Demand target\n         capacity is launched according to the On-Demand allocation strategy\n            (<code>lowest-price</code>).</p>\n         <p>If you do not specify a value, the fleet fulfills the On-Demand capacity according to\n         the chosen On-Demand allocation strategy.</p>"}))
    OnDemandCapacityReservationOptions.add_member(:capacity_reservation_preference, Smithy::Schema::Shapes::ShapeRef.new(shape: OnDemandCapacityReservationPreference, location_name: 'CapacityReservationPreference', traits: {"smithy.api#documentation" => "<p>Indicates the instance's Capacity Reservation preferences. Possible preferences\n         include:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>open</code> - The instance can run in any open Capacity Reservation that has\n               matching attributes (instance type, platform, Availability Zone).</p>\n            </li>\n            <li>\n               <p>\n                  <code>none</code> - The instance avoids running in a Capacity Reservation even if\n               one is available. The instance runs as an On-Demand Instance.</p>\n            </li>\n         </ul>"}))
    OnDemandCapacityReservationOptions.add_member(:capacity_reservation_resource_group_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen256, location_name: 'CapacityReservationResourceGroupArn', traits: {"smithy.api#documentation" => "<p>The ARN of the Capacity Reservation resource group in which to run the instance.</p>"}))
