    OnDemandProvisioningSpecification.add_member(:allocation_strategy, Smithy::Schema::Shapes::ShapeRef.new(shape: OnDemandProvisioningAllocationStrategy, location_name: 'AllocationStrategy', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>Specifies the strategy to use in launching On-Demand instance fleets. Available\n         options are <code>lowest-price</code> and <code>prioritized</code>. <code>lowest-price</code>\n      specifies to launch the instances with the lowest price first, and <code>prioritized</code> specifies\n      that Amazon EMR should launch the instances with the highest priority first. The default is\n      <code>lowest-price</code>.</p>", "smithy.api#required" => {}}))
