    PlacementType.add_member(:availability_zone, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlString, location_name: 'AvailabilityZone', traits: {"smithy.api#documentation" => "<p>The Amazon EC2 Availability Zone for the cluster. <code>AvailabilityZone</code>\n         is used for uniform instance groups, while <code>AvailabilityZones</code> (plural) is used\n         for instance fleets.</p>"}))
    PlacementType.add_member(:availability_zones, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen256List, location_name: 'AvailabilityZones', traits: {"smithy.api#documentation" => "<p>When multiple Availability Zones are specified, Amazon EMR evaluates them and\n         launches instances in the optimal Availability Zone. <code>AvailabilityZones</code> is used\n         for instance fleets, while <code>AvailabilityZone</code> (singular) is used for uniform\n         instance groups.</p>\n         <note>\n            <p>The instance fleet configuration is available only in Amazon EMR releases\n            4.8.0 and later, excluding 5.0.x versions.</p>\n         </note>"}))
